static void probe_latency_dump(void)
{
  uint32_t i;
  /* A full event line includes producer and completed-batch context.  Keep
   * it bounded but large enough that snprintf cannot silently suppress a
   * valid record. */
  char line[1024];
  uint64_t dump_begin_us = 0;
  uint64_t dump_end_us = 0;
  uint32_t dump_begin_generated = __atomic_load_n(&g_rank_generated,
                                                   __ATOMIC_ACQUIRE);
  uint32_t dump_begin_enqueued = __atomic_load_n(&g_serial_head,
                                                  __ATOMIC_ACQUIRE);
  uint32_t dump_begin_consumed = __atomic_load_n(&g_rank_samples_consumed,
                                                  __ATOMIC_ACQUIRE);
  uint32_t dump_begin_queue_full = __atomic_load_n(&g_serial_queue_full,
                                                    __ATOMIC_ACQUIRE);
  uint32_t dump_begin_tail = __atomic_load_n(&g_serial_tail,
                                              __ATOMIC_ACQUIRE);
  (void)probe_get_monotonic_us(&dump_begin_us);
  /* Freeze only the short metadata capture window.  Formatting and UART
   * output happen after the flag is released, so the consumer keeps
   * draining samples while a slow host reads the dump. */
  __atomic_store_n(&g_latency_dump_active, true, __ATOMIC_RELEASE);
  __atomic_thread_fence(__ATOMIC_SEQ_CST);
  (void)snprintf(line, sizeof(line),
    "BTE1 LATENCY_DUMP_BEGIN at_us=%llu generated=%lu enqueued=%lu consumed=%lu queue_full=%lu depth=%lu\n",
    (unsigned long long)dump_begin_us,
    (unsigned long)dump_begin_generated,
    (unsigned long)dump_begin_enqueued,
    (unsigned long)dump_begin_consumed,
    (unsigned long)dump_begin_queue_full,
    (unsigned long)(dump_begin_enqueued - dump_begin_tail));
  pthread_mutex_lock(&g_uart_write_lock);
  (void)write(STDOUT_FILENO, line, strlen(line));
  pthread_mutex_unlock(&g_uart_write_lock);
  __atomic_store_n(&g_latency_dump_active, false, __ATOMIC_RELEASE);
  g_batch_association_failures = 0;
  for (i = 0; i < g_latency_event_count; i++)
    {
      struct probe_latency_event_record *r = &g_latency_events[i];
      /* Resolve from the persistent batch archive before serializing the
       * event, so exported fields reflect the immutable association rather
       * than the producer/consumer race at event creation time. */
      if (!r->batch_complete_valid)
        {
          struct probe_batch_archive_record ab;
          if (probe_batch_archive_find(r->session, r->batch_id,
                                       r->recovery_generation, &ab))
            {
              r->batch_complete_samples = ab.complete_samples;
              r->batch_first_sequence = ab.first_sequence;
              r->batch_last_sequence = ab.last_sequence;
              r->batch_enqueue_success = ab.enqueue_success;
              r->batch_enqueue_failed = ab.enqueue_failed;
              r->batch_complete_valid = ab.valid;
              r->batch_assoc_reason = ab.valid ? PROBE_BATCH_ASSOC_OK : PROBE_BATCH_ASSOC_NOT_FOUND;
            }
        }
      int64_t a = (int64_t)r->confirmation_sample_us - (int64_t)r->beat_us;
      int64_t s = (int64_t)r->enqueue_us - (int64_t)r->confirmation_sample_us;
      int64_t q = (int64_t)r->hb_begin_us - (int64_t)r->enqueue_us;
      int64_t f = (int64_t)r->detected_us - (int64_t)r->hb_begin_us;
      int64_t sum = a + s + q + f;
      int n = snprintf(line, sizeof(line),
        "BTE1 LATENCY session=%lu event=%lu seq=%lu batch=%lu recovery=%lu beat_us=%llu confirmation_sample_us=%llu enqueue_us=%llu hb_begin_us=%llu hb_end_us=%llu detected_us=%llu algorithm_span_us=%lld sample_age_at_enqueue_us=%lld queue_wait_us=%lld feed_elapsed_us=%lld sum_us=%lld total_us=%lld producer_valid=%u fifo_before_us=%llu fifo_after_us=%llu pair_complete_us=%llu depth_words=%lu remaining_after=%lu estimator_sequence=%lu period_q16=%lu slew_us=%lld batch_complete_valid=%u batch_assoc_reason=%u batch_complete_samples=%lu batch_first_seq=%lu batch_last_seq=%lu batch_enqueue_ok=%lu batch_enqueue_failed=%lu batch_end_us=%llu\n",
        (unsigned long)r->session, (unsigned long)r->event_id,
        (unsigned long)r->source_sequence,
        (unsigned long)r->batch_id,
        (unsigned long)r->recovery_generation,
        (unsigned long long)r->beat_us,
        (unsigned long long)r->confirmation_sample_us,
        (unsigned long long)r->enqueue_us,
        (unsigned long long)r->hb_begin_us,
        (unsigned long long)r->hb_end_us,
        (unsigned long long)r->detected_us,
        (long long)a, (long long)s, (long long)q, (long long)f,
        (long long)sum,
        (long long)((int64_t)r->detected_us - (int64_t)r->beat_us),
        (unsigned)r->producer_context_valid,
        (unsigned long long)r->fifo_status_before_us,
        (unsigned long long)r->fifo_status_after_us,
        (unsigned long long)r->pair_complete_us,
        (unsigned long)r->fifo_depth_words,
        (unsigned long)r->remaining_after,
        (unsigned long)r->estimator_sequence,
        (unsigned long)r->estimator_period_q16,
        (long long)r->estimator_slew_us,
        (unsigned)r->batch_complete_valid,

