    "BTE1 LATENCY_DUMP_BEGIN at_us=%llu generated=%lu enqueued=%lu consumed=%lu queue_full=%lu depth=%lu\n",
    (unsigned long long)dump_begin_us,
    (unsigned long)dump_begin_generated,
    (unsigned long)dump_begin_enqueued,
    (unsigned long)dump_begin_consumed,
    (unsigned long)dump_begin_queue_full,
    (unsigned long)(dump_begin_enqueued - dump_begin_tail));
  pthread_mutex_lock(&g_uart_write_lock);
  (void)write(STDOUT_FILENO, line, strlen(line));
  pthread_mutex_unlock(&g_uart_write_lock);
  __atomic_store_n(&g_latency_dump_active, false, __ATOMIC_RELEASE);
  g_batch_association_failures = 0;
  for (i = 0; i < g_latency_event_count; i++)
    {
