      int64_t s = (int64_t)r->enqueue_us - (int64_t)r->confirmation_sample_us;
      int64_t q = (int64_t)r->hb_begin_us - (int64_t)r->enqueue_us;
      int64_t f = (int64_t)r->detected_us - (int64_t)r->hb_begin_us;
