  uint32_t count;
  uint32_t next;
  uint32_t i;

  pthread_mutex_lock(&g_batch_assoc_lock);
  count = g_batch_archive_count;
  if (count > PROBE_BATCH_ARCHIVE_DEPTH)
    count = PROBE_BATCH_ARCHIVE_DEPTH;
  next = g_batch_archive_next;
  for (i = 0; i < count; i++)
    {
      const struct probe_batch_archive_record *b =
        &g_batch_archive[(next + PROBE_BATCH_ARCHIVE_DEPTH - count + i) %
                         PROBE_BATCH_ARCHIVE_DEPTH];
      if (b->session == session && b->batch_id == batch_id &&
          b->recovery_generation == generation)
        {
          if (out != NULL)
            *out = *b;
          found = true;
          break;
        }
    }
  pthread_mutex_unlock(&g_batch_assoc_lock);
  return found;
}

