          session, batch_id, generation, 1};
        g_batch_pending_count++;
        pthread_mutex_unlock(&g_batch_assoc_lock);
        return true;
      }
  g_batch_pending_overflow++;
  pthread_mutex_unlock(&g_batch_assoc_lock);
  return false;
}

static void probe_batch_pending_complete(const struct probe_batch_trace_record *record)
{
  uint32_t i;
