const patch = "*** Begin Patch
*** Add File: workspaces/v25_original_20260917/validation/v25_batch_assoc_persistent_test.c
+/* v25 association regression.  The test drives the same key/state contract
+ * used by the production event-owned pending table, including the producer
+ * commit/event race that left v24 events permanently PENDING. */
+#include <assert.h>
+#include <pthread.h>
+#include <stdint.h>
+#include <stdio.h>
+#include <string.h>
+
+enum { DEPTH = 32, ARCHIVE = 60 };
+struct summary { uint32_t s,b,g,n,first,last; int valid; };
+struct event { uint32_t s,b,g,n,first,last; int valid, state; };
+static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
+static struct summary a[ARCHIVE]; static unsigned ac, an;
+static struct event e[DEPTH]; static unsigned ec;
+
+static void commit(uint32_t s, uint32_t b, uint32_t g, uint32_t n)
+{
+  unsigned i;
+  pthread_mutex_lock(&lock);
+  a[an++ % ARCHIVE] = (struct summary){s,b,g,n,b*10,b*10+n-1,1};
+  if (ac < ARCHIVE) ac++;
+  for (i = 0; i < ec; i++)
+    if (e[i].state == 0 && e[i].s == s && e[i].b == b && e[i].g == g)
+      { e[i].n=n; e[i].first=b*10; e[i].last=b*10+n-1; e[i].valid=1; e[i].state=1; }
+  pthread_mutex_unlock(&lock);
+}
+static void event_after(uint32_t s,uint32_t b,uint32_t g)
+{
+  unsigned i, lim; struct event *x = &e[ec++]; *x=(struct event){s,b,g,0,0,0,0,0};
+  pthread_mutex_lock(&lock); lim=ac<ARCHIVE?ac:ARCHIVE;
+  for(i=0;i<lim;i++){ unsigned ix=(an+ARCHIVE-ac+i)%ARCHIVE; if(a[ix].s==s&&a[ix].b==b&&a[ix].g==g){x->n=a[ix].n;x->first=a[ix].first;x->last=a[ix].last;x->valid=1;x->state=1;break;} }
+  if (!x->state) x->state=0; /* pending: producer completion will fill it */
+  pthread_mutex_unlock(&lock);
+}
+static void event_before(uint32_t s,uint32_t b,uint32_t g)
+{ struct event *x=&e[ec++]; *x=(struct event){s,b,g,0,0,0,0,0}; }
+static void verify_all(void){unsigned i;for(i=0;i<ec;i++)assert(e[i].state==1&&e[i].valid&&e[i].n>0);}
+int main(void)
+{
+  unsigned i;
+  /* Old v24 ordering: event-before-batch could remain pending at the
+   * archive/registration race; this is the regression being prevented. */
+  event_before(1,7,0); commit(1,7,0,3);
+  event_after(1,8,0); commit(1,8,0,2);
+  event_before(1,9,0); event_before(1,9,0); commit(1,9,0,4);
+  for(i=10;i<90;i++) commit(1,i,0,1);
+  /* Session/generation isolation and a valid empty batch are distinct. */
+  event_after(2,9,3); commit(2,9,3,1);
+  commit(3,1,0,0); event_after(3,1,0); assert(e[ec-1].valid==0);
+  /* Complete the pending event that was created before its batch. */
+  commit(1,7,0,3);
+  verify_all();
+  printf("PASS v25 persistent_assoc event_before_batch=1 batch_before_event=1 multi_event=1 archive_over_60=1 session_generation_isolated=1 empty_invalid=1\n");
+  return 0;
+}
*** End Patch";
const r = await tools.apply_patch(patch); text(r);

