#include <pthread.h>
#include <stdint.h>
#include <stdio.h>
#include <string.h>

enum { DEPTH = 32, ARCHIVE = 60 };
struct summary { uint32_t s,b,g,n,first,last; int valid; };
struct event { uint32_t s,b,g,n,first,last; int valid, state; };
static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
static struct summary a[ARCHIVE]; static unsigned ac, an;
static struct event e[DEPTH]; static unsigned ec;

static void commit(uint32_t s, uint32_t b, uint32_t g, uint32_t n)
{
  unsigned i;
  pthread_mutex_lock(&lock);
  a[an++ % ARCHIVE] = (struct summary){s,b,g,n,b*10,b*10+n-1,1};
  if (ac < ARCHIVE) ac++;
  for (i = 0; i < ec; i++)
    if (e[i].state == 0 && e[i].s == s && e[i].b == b && e[i].g == g)
      { e[i].n=n; e[i].first=b*10; e[i].last=b*10+n-1; e[i].valid=1; e[i].state=1; }
  pthread_mutex_unlock(&lock);
}
static void event_after(uint32_t s,uint32_t b,uint32_t g)
{
