  pthread_mutex_lock(&lock); lim=ac<ARCHIVE?ac:ARCHIVE;
  for(i=0;i<lim;i++){ unsigned ix=(an+ARCHIVE-ac+i)%ARCHIVE; if(a[ix].s==s&&a[ix].b==b&&a[ix].g==g){x->n=a[ix].n;x->first=a[ix].first;x->last=a[ix].last;x->valid=1;x->state=1;break;} }
