#endif
  while (__atomic_load_n(&g_serial_running, __ATOMIC_ACQUIRE) ||
         __atomic_load_n(&g_serial_tail, __ATOMIC_RELAXED) !=
         __atomic_load_n(&g_serial_head, __ATOMIC_ACQUIRE)
