                lr->source_sequence = he.source_sequence;
                lr->beat_us = he.beat_time_us;
                lr->confirmation_sample_us = he.confirmation_sample_us;
                lr->enqueue_us = sample.queued_at_us;
                lr->hb_begin_us = elapsed_start_us;
